          { objective: "O4", q: "Panga hizi kwa mpangilio kwa choo kinachotiririka: (a) badilisha flapper, (b) funga vali ya maji, (c) kagua kuvuja, (d) vuta maji ili kumwaga tangi.", options: ["b, d, a, c", "a, b, c, d", "d, a, b, c", "c, b, a, d"], answer: 0, why: "Funga maji, mwaga tangi, fanya matengenezo, kisha kagua kuvuja." },
          { objective: "O4", q: "Kazi ipi msaidizi mpya anapaswa kumwachia fundi bomba mwenye leseni?", options: ["Kutumia plunger kwenye sinki linalotoa maji polepole", "Kubadilisha flapper ya choo", "Kuhamisha bomba la gesi kwenda jiko jipya", "Kuweka ndoo chini ya trap"], answer: 2, why: "Kazi ya mabomba ya gesi inahitaji mafunzo na, katika baadhi ya majimbo, leseni maalum." },
          { objective: "O5", q: "Kwa mujibu wa BLS, mafundi bomba wengi hujifunza kazi hii vipi?", options: ["Darasa la mtandaoni la wiki mbili", "Shahada ya chuo ya miaka minne", "Kutazama video nyumbani", "Uanagenzi wa kulipwa wa miaka 4 au 5"], answer: 3, why: "BLS inasema wengi hujifunza kupitia uanagenzi wa miaka 4 au 5 wenye mafunzo kazini ya kulipwa." }
